    u_xlat11.x = u_xlat11.x * u_xlat22.x;
    u_xlat0.x = u_xlat11.x * u_xlat0.x;
    u_xlatb11 = 0<int(_enable_lighting);
    u_xlat3.xyz = _light_direction.xyz * vec3(0.5, -0.5, -2.0);
    u_xlat22.x = dot(u_xlat3.xyz, u_xlat3.xyz);
    u_xlat22.x = inversesqrt(u_xlat22.x);
    u_xlat3.xyz = u_xlat22.xxx * u_xlat3.xyz;
    u_xlat22.x = dot(u_xlat12.xyz, u_xlat3.xyz);
    u_xlat1.xyz = u_xlat2.xyz * _light_color.xyz;
    u_xlat1.xyz = u_xlat22.xxx * u_xlat1.xyz;
    u_xlat33 = (-_ambient) + 1.0;
    u_xlat1.xyz = vec3(u_xlat33) * u_xlat1.xyz;
    u_xlat1.xyz = u_xlat2.xyz * vec3(vec3(_ambient, _ambient, _ambient)) + u_xlat1.xyz;
    u_xlat1.xyz = u_xlat1.xyz * vec3(vec3(_light_intensity, _light_intensity, _light_intensity));
    u_xlat22.x = log2(u_xlat22.x);
    u_xlat22.x = u_xlat22.x * _specular;
    u_xlat22.x = exp2(u_xlat22.x);
    u_xlat33 = (-_shine) * 0.100000001 + 1.0;
    u_xlat3.xyz = vec3(u_xlat33) * u_xlat1.xyz;
    u_xlat22.x = u_xlat22.x * _shine;
    u_xlat1.xyz = (-u_xlat1.xyz) * vec3(u_xlat33) + vec3(1.0, 1.0, 1.0);
    u_xlat1.xyz = u_xlat22.xxx * u_xlat1.xyz + u_xlat3.xyz;
    u_xlat1.w = u_xlat2.w;
    u_xlat1 = u_xlat0.xxxx * u_xlat1;
    u_xlat2 = u_xlat0.xxxx * u_xlat2;
    u_xlat0 = (bool(u_xlatb11)) ? u_xlat1 : u_xlat2;
    if(int(_use_inner_mask) != 0) {
        u_xlat1 = texture(inputImg, acScreenNorm.xy);
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat0;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat1 = u_xlat1 * u_xlat5;
        u_xlat1 = u_xlat3 * u_xlat4 + u_xlat1;
        u_xlat2.x = u_xlat4.x * u_xlat1.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat1.w;
        fragColor.xyz = u_xlat1.xyz;
    } else {
        fragColor = u_xlat0;
    }
    return;
}
